#!/bin/sh
# Prints the deployment plan for one environment: sh deploy.sh dev|staging|prod
set -eu

# deploy_to ENV HOST REPLICAS: prints the plan for one environment.
deploy_to() {
    echo "deploy: target $1 ($2)"
    echo "deploy: sync build/ to $2:/srv/app"
    echo "deploy: restart app with $3 replica(s)"
    echo "deploy: check https://$2/healthz"
}

env=${1:-}
case $env in
    dev) deploy_to "$env" dev.internal.example 1 ;;
    staging) deploy_to "$env" staging.internal.example 2 ;;
    prod) deploy_to "$env" app.example 6 ;;
    *)
        echo "deploy: unknown environment '$env'" >&2
        exit 2
        ;;
esac
